        name: "description",
        content: appConfig.description,
      },
    ],
  },
  components: {
    Layout,
    PageHeader,
  },
  data() {
    return {
      selectedTap: true,
      configurations: [],
      customers: [],
      Customers: {},
      page: 1,
      limit: 20,
      tot_pages: 0,
      searchCustomers: null,
      CustomersSearchMode: false,
      tariff: [],
      neighborhood: [],
      addOptions: [{}],
      editOptions: [{}],
      option: "",
      data: {},
      config: [],
      editModalData: {},
      customer: {
        comboEnabled: false,
        selectedOption: "",
        tariff_id: "",
        neighborhood_id: "",
        name: "",
        meter_no: "",
        account_no: "",
        house_no: "",
        block: "",
        degree: "",
        add_date: "",
        recivable: { enabled: false, value: 0 },
        unearned: { enabled: false, value: 0 },
      },
      edit: [],
      optionsData: [],
      newOptions: [],
      select: [],
      branch_id: null,
      searchModel: "",
      currentStep: 1,
      circlesCount: 3,

      // appprices:[]
    };
  },
  computed: {
    pagesToShow() {
      const pages = [];
      const start = Math.max(1, this.page - 2);
      const end = Math.min(this.tot_pages, this.page + 2);

      for (let i = start; i <= end; i++) {
        pages.push(i);
      }

      return pages;
    },
    progressWidth() {
      return ((this.currentStep - 1) / (this.circlesCount - 1)) * 100 + "%";
    },
    isFirstStep() {
      return this.currentStep === 1;
    },
    isLastStep() {
      return this.currentStep === this.circlesCount;
    },
  },
  methods: {
    editCustomers(app) {
      console.log(app);
      this.edit = app;
    },
    editconfigdata(config) {
      this.editModalData = config;
      console.log("********", config);
      this.config = Object.assign([], config);
    },
    onChange(event) {
      console.log("_________", event.target.value);
      if (event.target.value == "select") {
        return (this.option = 3);
      }
    },
    addconfig() {
      if (this.data.option == "select") {
        this.http
          .post("emps/add-col", {
            table: "customers",
            data: this.data,
            options: this.addOptions,
          })
          .then(() => {
            this.getconfig(this.page);
          });
      } else {
        console.log("in else");
        console.log(this.data);
        this.http
          .post("emps/add-col", {
            table: "customers",
            data: this.data,
          })
          .then(() => {
            this.getconfig(this.page);
          });
