    editconfig() {
      console.log(")))*****", this.addOptions);
      if (this.editModalData.option == "select") {
        this.http
          .post("emps/edit-col", {
            table: "customers",
            options: this.editOptions,
            config: this.editModalData,
            config_id: this.editModalData.id,
          })
          .then(() => {
            this.get(1);
          });
      } else {
        delete this.editModalData.options;
        this.http
          .post("emps/edit-col", {
            table: "customers",
            config: this.editModalData,
            config_id: this.editModalData.id,
          })
          .then(() => {
            this.get(1);
          });
      }
