    deleteconfig(config) {
      var data = {
        title: "popups.deletecol",
        msg: "popups.delmessage",
      };
      this.popup.confirm(data).then((resp) => {
        if (resp) {
          console.log("###");
          this.http.delete("table-fileds", config.id).then(() => {
            console.log("############################3");
            this.getconfig(this.page);
          });
        }
      });
