      console.log(page);
      this.http
        .post("emps/get-cols", {
          table: "customers",
        })
        .then((res) => {
          this.configurations = res.data;
          for (let i = 0; i < this.configurations.length; i++) {
            this.configurations[i].options = JSON.parse(
              this.configurations[i].options
            );
            if (this.configurations[i].type == "int") {
