    goToPage(p) {
      if (p < 1 || p > this.tot_pages || p === this.page) return;
      this.page = p;
      this.searchModel ? this.search(p) : this.get(p);
    },
    nextStep() {
      if (this.currentStep < this.circlesCount) {
        this.currentStep++;
        this.tryNext = false;
      }
    },
    prevStep() {
      if (this.currentStep > 1) {
        this.currentStep--;
      }
    },
    handleSelectChange() {
      this.customer.recivable.enabled = false;
      this.customer.unearned.enabled = false;

      // Enable the selected one
      if (this.customer.selectedOption === "recivable") {
        this.customer.recivable.enabled = true;
      } else if (this.customer.selectedOption === "unearned") {
        this.customer.unearned.enabled = true;
      }
    },
  },
  created() {
    const current_user = JSON.parse(localStorage.currentUser);
    this.branch_id = current_user.branch_id;
    this.get(1);
    // this.getCustomers();
    this.getconfig();
    this.gitTariff();
    this.gitNeighborhood();

    // this.loopOnArray()
  },
};
